-- Datos ficticios de Services Vales exportados de PostgreSQL el 8 de noviembre de 2026.
-- Carga de una sola vez en una base de prueba recién migrada.
BEGIN;
SET LOCAL standard_conforming_strings = on;
SET LOCAL search_path = vales, pg_catalog;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM persona) OR EXISTS (SELECT 1 FROM contrato_vale)
       OR EXISTS (SELECT 1 FROM factura) THEN
        RAISE EXCEPTION 'La copia de prueba requiere una base recién migrada sin registros operativos.';
    END IF;
END;
$$;

-- Se reemplazan los catálogos iniciales por los que acompañan a los vales del respaldo.
TRUNCATE zonal, localidad, unidad_organizativa, centro_costo, asignacion_costo, persona, unidad_maquinaria, trabajador, tercero, proveedor, suministro, estado_vale, rol, usuario, usuario_rol, contrato_vale, contrato_suministro, tarifa, factura, correlativo_vale, correlativo_ticket, vales, historial_vale, historial_acceso;
























ALTER SEQUENCE factura_codigo_factura_seq RESTART WITH 78;
ALTER SEQUENCE historial_acceso_id_seq RESTART WITH 1;
ALTER SEQUENCE historial_vale_id_evento_seq RESTART WITH 527;
ALTER SEQUENCE tercero_codigo_tercero_seq RESTART WITH 2;
ALTER SEQUENCE trabajador_id_trabajador_seq RESTART WITH 28;
ALTER SEQUENCE unidad_maquinaria_codigo_seq RESTART WITH 7;
ALTER SEQUENCE usuario_id_usuario_seq RESTART WITH 26;
ALTER SEQUENCE vales_id_vale_seq RESTART WITH 179;

COMMIT;
